import React, { useState, Fragment } from "react";
import { useHistory } from "react-router-dom";
import axios from "axios";
import Header from "../Header/Header";

const Create = () => {
  const history = useHistory();
  const userString = localStorage.getItem("user");
  const savedUser = userString ? JSON.parse(userString) : null;

  const [name, setName] = useState("");
  const [category, setCategory] = useState("");
  const [price, setPrice] = useState("");
  const [location, setLocation] = useState("");
  const [sellerPhone, setSellerPhone] = useState(savedUser?.phone || "");
  const [description, setDescription] = useState("");
  const [image, setImage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const token = localStorage.getItem("token");

    if (!savedUser) {
      alert("Please login first!");
      history.push("/login");
      return;
    }

    try {
      const currentSellerId = savedUser._id || savedUser.id;

      const postData = {
        title: name,
        category,
        price: Number(price),
        location,
        description,
        imageUrl: image,
        sellerId: currentSellerId,
        sellerName: savedUser.name || "Thrift Shop Seller",
        sellerPhone
      };

      await axios.post("http://localhost:5000/api/posts", postData, {
        headers: {
          Authorization: token ? `Bearer ${token}` : ""
        }
      });

      alert("Product listed successfully!");
      history.push("/");
    } catch (error) {
      console.error("Error creating post:", error.response?.data || error.message);
      alert(error.response?.data?.error || error.response?.data?.message || "Failed to create post. Check console for details.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Fragment>
      <Header />
      <div style={{ maxWidth: "500px", margin: "40px auto", padding: "25px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)" }}>
        <h2 style={{ color: "#002f34", marginBottom: "20px", textAlign: "center" }}>Sell Your Product</h2>
        
        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Product Title</label>
            <input
              type="text"
              required
              placeholder="e.g., Original Puma Sneakers or Vintage Denim Jacket"
              value={name}
              onChange={(e) => setName(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Category</label>
            <select
              required
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            >
              <option value="">Select Category</option>
              <option value="Clothing">Clothing</option>
              <option value="Footwear">Footwear</option>
              <option value="Accessories">Accessories</option>
              <option value="Gadgets">Gadgets</option>
              <option value="Books">Books</option>
            </select>
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Price (₹)</label>
            <input
              type="number"
              required
              placeholder="e.g., 1500"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Location</label>
            <input
              type="text"
              required
              placeholder="e.g., Kanpur, Uttar Pradesh"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Seller Mobile / WhatsApp Number</label>
            <input
              type="tel"
              required
              placeholder="e.g., 9876543210"
              value={sellerPhone}
              onChange={(e) => setSellerPhone(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Description</label>
            <textarea
              rows="3"
              required
              placeholder="Describe the condition and details of your item..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>

          <div>
            <label style={{ fontWeight: "bold", display: "block", marginBottom: "5px", color: "#002f34" }}>Product Image</label>
            <input
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              style={{ marginBottom: "10px" }}
            />
            {image && (
              <div style={{ marginTop: "10px", textAlign: "center" }}>
                <img src={image} alt="Preview" style={{ width: "180px", height: "180px", objectFit: "cover", borderRadius: "6px", border: "1px solid #ddd" }} />
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={loading}
            style={{ padding: "12px", backgroundColor: "#002f34", color: "white", fontWeight: "bold", border: "none", borderRadius: "4px", cursor: "pointer", fontSize: "16px", marginTop: "10px" }}
          >
            {loading ? "Posting..." : "Post Now"}
          </button>
        </form>
      </div>
    </Fragment>
  );
};

export default Create;
